def gen_test(func=None, timeout=None):
    """Testing equivalent of ``@gen.coroutine``, to be applied to test methods.

    ``@gen.coroutine`` cannot be used on tests because the `.IOLoop` is not
    already running.  ``@gen_test`` should be applied to test methods
    on subclasses of `AsyncTestCase`.

    Example::

        class MyTest(AsyncHTTPTestCase):
            @gen_test
            def test_something(self):
                response = yield gen.Task(self.fetch('/'))

    By default, ``@gen_test`` times out after 5 seconds. The timeout may be
    overridden globally with the TIMEOUT environment variable, or for each
    test with the ``timeout`` keyword argument:

        class MyTest(AsyncHTTPTestCase):
            @gen_test(timeout=10)
            def test_something_slow(self):
                response = yield gen.Task(self.fetch('/'))

    If both the environment variable and the parameter are set, ``gen_test``
    uses the maximum of the two.
    """
    try:
        env_timeout = float(os.environ.get('TIMEOUT'))
    except (ValueError, TypeError):
        env_timeout = None

    def wrap(f):
        f = gen.coroutine(f)

        @functools.wraps(f)
        def wrapper(self):
            return self.io_loop.run_sync(
                functools.partial(f, self), timeout=timeout)
        return wrapper

    if func is not None:
        # Used like:
        #     @gen_test
        #     def f(self):
        #         pass
        timeout = env_timeout or 5
        return wrap(func)
    else:
        # Used like @gen_test(timeout=10)
        timeout = float(timeout)
        return wrap


